(function () {
'use strict';
var form = document.getElementById('cinv-form');
if (!form) return;
var table = form.querySelector('[data-cinv-sheet]');
var head = table.querySelector('[data-cinv-head]');
var body = table.querySelector('[data-cinv-rows]');
var toolbar = form.querySelector('.xl-toolbar');
var namebox = form.querySelector('[data-cinv-namebox]');
var payload = form.querySelector('[data-cinv-payload]');
var currencyField = form.querySelector('[data-cinv-currency]');
var taxField = form.querySelector('[data-cinv-tax]');
var WORDS = JSON.parse(form.getAttribute('data-currency-words') || '{}');
var DECIMALS = JSON.parse(form.getAttribute('data-decimals') || '{}');
var MAX_ROWS = parseInt(form.getAttribute('data-max-lines') || '100', 10);
var MAX_COLS = parseInt(form.getAttribute('data-max-columns') || '5', 10);
var nextKey = parseInt(form.getAttribute('data-next-key') || '2', 10);
var ALIGNS = ['left', 'center', 'right'];
var active = null;          // cellule active : <td> ou <th>
var scope = 'cell';         // portée de l'alignement : 'cell' ou 'column'
var cur = function () { return currencyField.value; };
var dec = function () { return DECIMALS[cur()] != null ? DECIMALS[cur()] : 2; };
var num = function (v) {
var n = parseFloat(String(v).replace(/[\s  ]/g, '').replace(',', '.'));
return isFinite(n) ? n : NaN;
};
var round = function (v, d) { var f = Math.pow(10, d); return Math.round(v * f) / f; };
var fmt = function (v) { return new Intl.NumberFormat('fr-FR', { minimumFractionDigits: dec(), maximumFractionDigits: dec() }).format(v); };
var label = function () { return cur() === 'XAF' ? 'FCFA' : cur(); };
var text = function (el) {
if (!el) return '';
var raw = el.hasAttribute('data-cinv-label') ? el.textContent : el.innerText;
return raw.replace(/\u00A0/g, ' ').replace(/\n+$/, '').trim();
};
var rows = function () { return Array.prototype.slice.call(body.querySelectorAll('[data-cinv-row]')); };
var heads = function () { return Array.prototype.slice.call(head.querySelectorAll('th[data-col]')); };
var textHeads = function () { return heads().filter(function (th) { return th.getAttribute('data-col') !== 'amount'; }); };
var cellOf = function (row, key) { return row.querySelector('td[data-col="' + key + '"]'); };
var headOf = function (key) { return head.querySelector('th[data-col="' + key + '"]'); };
var colLabel = function (key) {
var th = headOf(key);
return text(th && th.querySelector('[data-cinv-label]')) || (key === 'amount' ? 'Montant' : 'Colonne sans titre');
};
var isEmpty = function (row) {
return Array.prototype.every.call(row.querySelectorAll('[data-cinv-cell]'), function (c) { return text(c) === ''; });
};
var setAlignClass = function (el, align) {
ALIGNS.forEach(function (a) { el.classList.remove('is-' + a); });
el.classList.add('is-' + align);
};
var alignOf = function (td) {
if (td.hasAttribute('data-align')) return td.getAttribute('data-align');
var th = headOf(td.getAttribute('data-col'));
return th ? th.getAttribute('data-align') : 'left';
};
var UNITS = ['zéro', 'un', 'deux', 'trois', 'quatre', 'cinq', 'six', 'sept', 'huit', 'neuf', 'dix',
'onze', 'douze', 'treize', 'quatorze', 'quinze', 'seize'];
var TENS = { 2: 'vingt', 3: 'trente', 4: 'quarante', 5: 'cinquante', 6: 'soixante' };
var below100 = function (n) {
if (n < 17) return UNITS[n];
if (n < 20) return 'dix-' + UNITS[n - 10];
var t = Math.floor(n / 10), u = n % 10;
if (t === 7 || t === 9) return t === 7 && u === 1 ? 'soixante et onze' : (t === 7 ? 'soixante' : 'quatre-vingt') + '-' + below100(10 + u);
if (t === 8) return u === 0 ? 'quatre-vingts' : 'quatre-vingt-' + UNITS[u];
return u === 0 ? TENS[t] : (u === 1 ? TENS[t] + ' et un' : TENS[t] + '-' + UNITS[u]);
};
var below1000 = function (n, final) {
var h = Math.floor(n / 100), r = n % 100, parts = [];
if (h === 1) parts.push('cent');
else if (h > 1) parts.push(below100(h) + (r === 0 && final ? ' cents' : ' cent'));
if (r > 0 || h === 0) parts.push(below100(r));
return parts.join(' ');
};
var words = function (n) {
if (n === 0) return 'zéro';
var out = [];
[[1e9, 'milliard'], [1e6, 'million']].forEach(function (p) {
var c = Math.floor(n / p[0]);
if (c > 0) { out.push(below1000(c, true) + ' ' + p[1] + (c > 1 ? 's' : '')); n %= p[0]; }
});
var th = Math.floor(n / 1000);
if (th > 0) { out.push(th === 1 ? 'mille' : below1000(th, false).replace(/(vingt|cent)s$/, '$1') + ' mille'); n %= 1000; }
if (n > 0) out.push(below1000(n, true));
return out.join(' ');
};
var amountWords = function (amount) {
var w = WORDS[cur()] || [cur(), cur()];
amount = round(Math.abs(amount), dec());
var whole = Math.floor(amount + 1e-9);
var cents = dec() > 0 ? Math.round((amount - whole) * 100) : 0;
if (whole > 999999999999) return '';
var t = words(whole);
var of = /(million|milliard)s?$/.test(t) ? (/^[aeiouyéè]/i.test(w[1]) ? " d'" : ' de ') : ' ';
t += of + (whole > 1 ? w[1] : w[0]);
if (cents > 0) t += ' et ' + words(cents) + ' centime' + (cents > 1 ? 's' : '');
return t.charAt(0).toUpperCase() + t.slice(1);
};
var makeCell = function (key, align) {
var td = document.createElement('td');
td.setAttribute('data-col', key);
setAlignClass(td, align);
if (key === 'amount') td.classList.add('sheet__amount');
var div = document.createElement('div');
div.className = 'xl-cell';
div.contentEditable = 'true';
div.setAttribute('role', 'textbox');
div.setAttribute('data-cinv-cell', '');
if (key === 'amount') { div.setAttribute('inputmode', 'decimal'); div.setAttribute('data-cinv-amount', ''); }
else div.setAttribute('aria-multiline', 'true');
td.appendChild(div);
return td;
};
var makeHead = function (key) {
var th = document.createElement('th');
th.className = 'sheet__col is-left';
th.setAttribute('scope', 'col');
th.setAttribute('data-col', key);
th.setAttribute('data-align', 'left');
th.innerHTML = '<div class="sheet__head"><div class="xl-cell xl-cell--head" contenteditable="true" spellcheck="false" role="textbox" aria-label="Titre de la colonne" data-cinv-label data-placeholder="Titre de colonne"></div></div>';
return th;
};
var makeRow = function () {
var tr = document.createElement('tr');
tr.setAttribute('data-cinv-row', '');
var n = document.createElement('td');
n.className = 'sheet__n';
n.setAttribute('data-cinv-n', '');
tr.appendChild(n);
heads().forEach(function (th) { tr.appendChild(makeCell(th.getAttribute('data-col'), th.getAttribute('data-align'))); });
return tr;
};
var refresh = function () {
rows().forEach(function (row, i) {
row.querySelector('[data-cinv-n]').textContent = i + 1;
row.querySelectorAll('td[data-col]').forEach(function (td) {
td.querySelector('[data-cinv-cell]').setAttribute('aria-label', colLabel(td.getAttribute('data-col')) + ', ligne ' + (i + 1));
});
});
var isCell = active && active.tagName === 'TD';
var key = active && active.getAttribute('data-col');
var btn = function (name) { return toolbar.querySelector('[data-xl="' + name + '"]'); };
btn('row-add').disabled = rows().length >= MAX_ROWS + 1;
btn('row-del').disabled = !isCell;
btn('col-add').disabled = textHeads().length >= MAX_COLS;
btn('col-del').disabled = !active || key === 'amount' || textHeads().length <= 1;
var current = active ? (isCell && scope === 'cell' ? alignOf(active) : headOf(key).getAttribute('data-align')) : null;
toolbar.querySelectorAll('[data-xl-align]').forEach(function (b) {
b.disabled = !active;
b.setAttribute('aria-pressed', String(b.getAttribute('data-xl-align') === current));
});
if (!active) namebox.textContent = '—';
else if (isCell) namebox.textContent = colLabel(key) + ' · ligne ' + (rows().indexOf(active.parentElement) + 1);
else namebox.textContent = 'Titre : ' + colLabel(key);
table.querySelectorAll('.is-active, .is-active-row, .is-active-col').forEach(function (el) { el.classList.remove('is-active', 'is-active-row', 'is-active-col'); });
if (active) {
active.classList.add('is-active');
if (isCell) active.parentElement.querySelector('[data-cinv-n]').classList.add('is-active-row');
headOf(key).classList.add('is-active-col');
}
};
var setActive = function (cell) { active = cell; refresh(); };
var focusCell = function (td) {
if (!td) return;
var el = td.querySelector('[contenteditable]');
el.focus();
var range = document.createRange();
range.selectNodeContents(el);
range.collapse(false);
var sel = window.getSelection();
sel.removeAllRanges();
sel.addRange(range);
};
var addRow = function (after) {
if (rows().length >= MAX_ROWS + 1) return null;
var tr = makeRow();
if (after && after.nextElementSibling) body.insertBefore(tr, after.nextElementSibling);
else body.appendChild(tr);
refresh();
return tr;
};
var ensureBlankRow = function () {
var all = rows();
if (!all.length || !isEmpty(all[all.length - 1])) addRow(null);
};
var deleteRow = function () {
if (!active || active.tagName !== 'TD') return;
var row = active.parentElement, key = active.getAttribute('data-col');
var target = row.nextElementSibling || row.previousElementSibling;
if (!isEmpty(row) && !window.confirm('Supprimer la ligne ' + (rows().indexOf(row) + 1) + ' et son contenu ?')) return;
row.remove();
active = null;
ensureBlankRow();
recalc();
refresh();
if (target && target.isConnected) focusCell(cellOf(target, key));
};
var addColumn = function () {
if (textHeads().length >= MAX_COLS) return;
var key = 'c' + (nextKey++);
var refKey = active ? active.getAttribute('data-col') : null;
var before = refKey && refKey !== 'amount' ? headOf(refKey).nextElementSibling : headOf('amount');
var beforeKey = before.getAttribute('data-col');
head.insertBefore(makeHead(key), before);
rows().forEach(function (row) { row.insertBefore(makeCell(key, 'left'), cellOf(row, beforeKey)); });
refresh();
var th = headOf(key);
th.querySelector('[data-cinv-label]').focus();
setActive(th);
};
var deleteColumn = function () {
if (!active) return;
var key = active.getAttribute('data-col');
if (key === 'amount' || textHeads().length <= 1) return;
var hasData = rows().some(function (row) { return text(cellOf(row, key).querySelector('[data-cinv-cell]')) !== ''; });
if (hasData && !window.confirm('Supprimer la colonne « ' + colLabel(key) + ' » et son contenu ?')) return;
headOf(key).remove();
rows().forEach(function (row) { cellOf(row, key).remove(); });
active = null;
refresh();
};
var align = function (value) {
if (!active || ALIGNS.indexOf(value) < 0) return;
var key = active.getAttribute('data-col');
if (scope === 'column' || active.tagName === 'TH') {
var th = headOf(key);
th.setAttribute('data-align', value);
setAlignClass(th, value);
rows().forEach(function (row) {
var td = cellOf(row, key);
td.removeAttribute('data-align');
setAlignClass(td, value);
});
} else {
active.setAttribute('data-align', value);
setAlignClass(active, value);
}
refresh();
};
var recalc = function () {
var subtotal = 0, d = dec(), bad = false;
rows().forEach(function (row) {
var cell = row.querySelector('[data-cinv-amount]');
var v = text(cell);
var invalid = v !== '' && isNaN(num(v));
cell.parentElement.classList.toggle('is-invalid', invalid);
if (v === '') return;
if (invalid) { bad = true; return; }
subtotal += round(num(v), d);
});
subtotal = round(subtotal, d);
var rate = num(taxField.value || '0');
if (!(rate >= 0 && rate <= 100)) rate = 0;
var tax = round(subtotal * rate / 100, d);
var total = round(subtotal + tax, d);
form.querySelector('[data-cinv-subtotal]').textContent = fmt(subtotal) + ' ' + label();
form.querySelector('[data-cinv-taxamount]').textContent = fmt(tax) + ' ' + label();
form.querySelector('[data-cinv-total]').textContent = fmt(total) + ' ' + label() + (bad ? ' (montant invalide)' : '');
form.querySelector('[data-cinv-words]').textContent = total > 0 ? amountWords(total) : '';
};
table.addEventListener('focusin', function (e) {
var cell = e.target.closest('td[data-col], th[data-col]');
if (cell) setActive(cell);
});
table.addEventListener('input', function (e) {
var el = e.target.closest('[contenteditable]');
if (!el) return;
if (text(el) === '' && el.innerHTML !== '') el.innerHTML = '';   // cellule vidée : le texte d'aide réapparaît
if (el.hasAttribute('data-cinv-label')) { refresh(); return; }
ensureBlankRow();
recalc();
});
table.addEventListener('paste', function (e) {
var el = e.target.closest('[contenteditable]');
if (!el) return;
e.preventDefault();
var t = (e.clipboardData || window.clipboardData).getData('text/plain') || '';
if (el.hasAttribute('data-cinv-amount') || el.hasAttribute('data-cinv-label')) t = t.replace(/[\r\n]+/g, ' ');
document.execCommand('insertText', false, t);
});
table.addEventListener('keydown', function (e) {
var el = e.target.closest('[contenteditable]');
if (!el) return;
var cell = el.closest('td, th');
var key = cell.getAttribute('data-col');
var multiline = el.hasAttribute('data-cinv-cell') && !el.hasAttribute('data-cinv-amount');
var target = null;
if (e.key === 'Enter' && !(e.shiftKey && multiline)) {
e.preventDefault();
if (cell.tagName === 'TH') target = rows()[0];
else target = cell.parentElement.nextElementSibling || addRow(cell.parentElement);
} else if (e.key === 'ArrowDown' && !e.shiftKey) {
target = cell.tagName === 'TH' ? rows()[0] : cell.parentElement.nextElementSibling;
} else if (e.key === 'ArrowUp' && !e.shiftKey && cell.tagName === 'TD') {
target = cell.parentElement.previousElementSibling;
if (!target) { e.preventDefault(); headOf(key).querySelector('[data-cinv-label]').focus(); return; }
}
if (target) {
e.preventDefault();
focusCell(cellOf(target, key));
}
});
toolbar.addEventListener('mousedown', function (e) { if (e.target.closest('button')) e.preventDefault(); });
toolbar.addEventListener('click', function (e) {
var b = e.target.closest('button');
if (!b || b.disabled) return;
var action = b.getAttribute('data-xl');
if (action === 'row-add') {
var tr = addRow(active && active.tagName === 'TD' ? active.parentElement : null);
if (tr) focusCell(cellOf(tr, active ? active.getAttribute('data-col') : heads()[0].getAttribute('data-col')));
recalc();
} else if (action === 'row-del') deleteRow();
else if (action === 'col-add') addColumn();
else if (action === 'col-del') deleteColumn();
else if (b.hasAttribute('data-xl-align')) align(b.getAttribute('data-xl-align'));
else if (b.hasAttribute('data-xl-scope')) {
scope = b.getAttribute('data-xl-scope');
toolbar.querySelectorAll('[data-xl-scope]').forEach(function (s) {
var on = s === b;
s.classList.toggle('is-active', on);
s.setAttribute('aria-checked', String(on));
});
refresh();
}
});
taxField.addEventListener('input', recalc);
currencyField.addEventListener('change', recalc);
form.querySelectorAll('[data-cinv-tax-preset]').forEach(function (b) {
b.addEventListener('click', function () { taxField.value = b.getAttribute('data-cinv-tax-preset'); recalc(); });
});
form.addEventListener('submit', function () {
payload.innerHTML = '';
var add = function (name, value) {
var input = document.createElement('input');
input.type = 'hidden';
input.name = name;
input.value = value;
payload.appendChild(input);
};
heads().forEach(function (th) {
add('col_key[]', th.getAttribute('data-col'));
add('col_label[]', text(th.querySelector('[data-cinv-label]')));
add('col_align[]', th.getAttribute('data-align'));
});
rows().forEach(function (row) {
heads().forEach(function (th) {
var key = th.getAttribute('data-col');
var td = cellOf(row, key);
add('cell[' + key + '][]', text(td.querySelector('[data-cinv-cell]')));
add('cell_align[' + key + '][]', td.getAttribute('data-align') || '');
});
});
});
var all = rows();
for (var i = all.length - 1; i > 0 && isEmpty(all[i]) && isEmpty(all[i - 1]); i--) all[i].remove();
ensureBlankRow();
refresh();
recalc();
})();
